export function initAdminSales({container,api}){
 const section=document.createElement('section');section.className='admin-sales';section.id='admin-sales';section.innerHTML='<div class="sales-heading"><div><p class="sales-kicker">SUA LOJA</p><h2>Vendas</h2></div><button type="button" class="sales-refresh quiet">Atualizar vendas</button></div><p>Acompanhe as compras feitas na loja. Presentes de teste e pagamentos de teste não entram aqui.</p><div class="sales-summary" aria-label="Resumo de vendas"></div><p class="sales-note">Total bruto das compras atualmente aprovadas, sem descontar taxas. Valores cancelados ou reembolsados não entram nesse total.</p><div class="sales-controls"><label>Situação <select class="sales-filter"><option value="all">Todas</option><option value="approved">Aprovadas</option><option value="pending">Pendentes</option><option value="failed">Não aprovadas</option><option value="revoked">Canceladas ou reembolsadas</option></select></label></div><p class="sales-status" role="status" aria-live="polite"></p><div class="sales-list" aria-label="Compras"></div><div class="sales-paging"><button type="button" class="sales-prev quiet">Anterior</button><span class="sales-page"></span><button type="button" class="sales-next quiet">Próxima</button></div>';container.append(section);
 const $=s=>section.querySelector(s),list=$('.sales-list'),status=$('.sales-status');let page=1,total=0,size=50,version=0,busy=false;
 const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n/100),date=n=>n?new Date(n*1000).toLocaleString('pt-BR'):'—',states={approved:'Aprovada',pending:'Pendente',failed:'Não aprovada',revoked:'Cancelada ou reembolsada'},plans={mimo:'Um Mimo',historia:'Uma História',celebrar:'Celebrar Juntos'},formats={cartao:'Cartão',livro:'Livro',convite:'Convite',stories:'Stories'};
 function clear(){version++;list.replaceChildren();$('.sales-summary').replaceChildren();$('.sales-page').textContent='';status.textContent='';page=1;total=0;busy=false;}
 function metric(label,value){const item=document.createElement('div'),name=document.createElement('span'),number=document.createElement('strong');name.textContent=label;number.textContent=value;item.append(name,number);return item;}
 async function load(){const own=++version;busy=true;status.textContent='Carregando vendas…';$('.sales-refresh').disabled=true;try{const data=await api('sales?page='+page+'&status='+encodeURIComponent($('.sales-filter').value));if(own!==version)return;total=data.total;size=data.pageSize;const summary=$('.sales-summary');summary.replaceChildren(metric('Compras aprovadas',data.summary.approved),metric('Valor bruto aprovado',money(data.summary.grossCents)),metric('Pendentes',data.summary.pending));list.replaceChildren();if(!data.sales.length){const p=document.createElement('p');p.textContent='Nenhuma compra encontrada para este filtro.';list.append(p);}for(const sale of data.sales){const card=document.createElement('article'),header=document.createElement('div'),title=document.createElement('strong'),badge=document.createElement('span'),email=document.createElement('p'),details=document.createElement('p'),id=document.createElement('small');card.className='sales-card';header.className='sales-card-heading';title.textContent=(plans[sale.planId]||sale.planId)+' · '+money(sale.amountCents);badge.className='sales-badge';badge.textContent=states[sale.status]||'Situação desconhecida';header.append(title,badge);email.textContent=sale.buyerEmail?'Comprador: '+sale.buyerEmail+(sale.emailVerified?' · conta verificada':' · e-mail informado'):'Comprador: e-mail não informado';details.textContent='Criada em '+date(sale.createdAt)+(sale.approvedAt?' · Aprovada em '+date(sale.approvedAt):'')+(sale.format?' · '+(formats[sale.format]||sale.format):'')+(sale.published?' · Presente publicado':' · Ainda não publicado');id.textContent='Compra: '+sale.id;card.append(header,email,details,id);list.append(card);}const pages=Math.max(1,Math.ceil(total/size));$('.sales-page').textContent='Página '+page+' de '+pages+' · '+total+' compra(s)';$('.sales-prev').disabled=page<=1;$('.sales-next').disabled=page>=pages;status.textContent='Vendas atualizadas.';}catch(error){if(own===version)status.textContent=error.message||'Não foi possível carregar as vendas.';}finally{if(own===version){busy=false;$('.sales-refresh').disabled=false;}}}
 $('.sales-refresh').addEventListener('click',()=>{if(!busy)load()});$('.sales-filter').addEventListener('change',()=>{page=1;load()});$('.sales-prev').addEventListener('click',()=>{if(!busy&&page>1){page--;load();}});$('.sales-next').addEventListener('click',()=>{if(!busy&&page*size<total){page++;load();}});
 return {load,clear};
}
